use crate::error::{Error, Result};

use std::{io::Write, process::Stdio};
use unicode_normalization::UnicodeNormalization;

/// Maximum length of a slug generated by `slugify`. Longer slugs are cut at
/// the last word boundary that fits.
pub const MAX_SLUG_LEN: usize = 32;

pub fn slugify(s: &str) -> String {
    let slug: String = s
        .trim()
        .nfd()
        .map(|c| if c.is_whitespace() { '-' } else { c })
        .filter(|c| c.is_ascii_alphanumeric() || c == &'_' || c == &'-')
        .map(|c| char::to_ascii_lowercase(&c))
        .scan(None, |last_char, char| {
            if char == '-' && last_char == &Some('-') {
                Some(None)
            } else {
                *last_char = Some(char);
                Some(Some(char))
            }
        })
        .flatten()
        .collect();
    truncate_slug(slug.trim_matches('-'), MAX_SLUG_LEN)
}

fn truncate_slug(slug: &str, max_len: usize) -> String {
    if slug.len() <= max_len {
        return slug.to_string();
    }
    // The slug is pure ASCII, so byte indexing is safe.
    let cut = &slug[..max_len];
    let cut = match cut.rfind('-') {
        Some(idx) if slug.as_bytes()[max_len] != b'-' && idx > 0 => &cut[..idx],
        _ => cut,
    };
    cut.trim_end_matches('-').to_string()
}

pub fn parse_name_list(text: &str) -> Vec<String> {
    lazy_regex::regex!(r#"\(.*?\)"#)
        .replace_all(text, ",")
        .split(',')
        .map(|name| name.trim())
        .filter(|name| !name.is_empty())
        .map(String::from)
        .collect()
}

pub fn remove_all_parens(text: &str) -> String {
    lazy_regex::regex!(r#"[()]"#).replace_all(text, "").into()
}

pub async fn run_command(cmd: &mut tokio::process::Command) -> Result<()> {
    let cmd_output = cmd
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()?
        .wait_with_output()
        .await?;

    if !cmd_output.status.success() {
        console::Term::stderr().write_all(&cmd_output.stderr)?;
        return Err(Error::new("command failed"));
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    // Note this useful idiom: importing names from outer (for mod tests) scope.
    use super::*;

    #[test]
    fn test_empty() {
        assert_eq!(slugify(""), "".to_string());
    }

    #[test]
    fn test_hello_world() {
        assert_eq!(slugify(" Hello  World! "), "hello-world".to_string());
    }

    #[test]
    fn test_accents() {
        assert_eq!(slugify("ĥêlļō ŵöřľď"), "hello-world".to_string());
    }

    #[test]
    fn test_truncates_long_titles_at_word_boundary() {
        let slug = slugify("Add support for very long pull request titles in branch names");
        assert_eq!(slug, "add-support-for-very-long-pull");
        assert!(slug.len() <= MAX_SLUG_LEN);
    }

    #[test]
    fn test_truncates_single_long_word() {
        let slug = slugify(&"a".repeat(50));
        assert_eq!(slug, "a".repeat(MAX_SLUG_LEN));
    }

    #[test]
    fn test_truncates_exactly_at_word_end() {
        // 32 chars that end exactly on a word boundary
        let title = "abcdefghij abcdefghij abcdefghij x";
        assert_eq!(slugify(title), "abcdefghij-abcdefghij-abcdefghij");
    }

    #[test]
    fn test_strips_edge_dashes() {
        assert_eq!(slugify("- hello -"), "hello");
    }

    #[test]
    fn test_parse_name_list_empty() {
        assert!(parse_name_list("").is_empty());
        assert!(parse_name_list(" ").is_empty());
        assert!(parse_name_list("  ").is_empty());
        assert!(parse_name_list("   ").is_empty());
        assert!(parse_name_list("\n").is_empty());
        assert!(parse_name_list(" \n ").is_empty());
    }

    #[test]
    fn test_parse_name_single_name() {
        assert_eq!(parse_name_list("foo"), vec!["foo".to_string()]);
        assert_eq!(parse_name_list("foo  "), vec!["foo".to_string()]);
        assert_eq!(parse_name_list("  foo"), vec!["foo".to_string()]);
        assert_eq!(parse_name_list("  foo  "), vec!["foo".to_string()]);
        assert_eq!(parse_name_list("foo (Foo Bar)"), vec!["foo".to_string()]);
        assert_eq!(
            parse_name_list("  foo (Foo Bar)  "),
            vec!["foo".to_string()]
        );
        assert_eq!(
            parse_name_list(" () (-)foo (Foo Bar)  (xx)"),
            vec!["foo".to_string()]
        );
    }

    #[test]
    fn test_parse_name_multiple_names() {
        let expected = vec!["foo".to_string(), "bar".to_string(), "baz".to_string()];
        assert_eq!(parse_name_list("foo,bar,baz"), expected);
        assert_eq!(parse_name_list("foo, bar, baz"), expected);
        assert_eq!(parse_name_list("foo , bar , baz"), expected);
        assert_eq!(
            parse_name_list("foo (Mr Foo), bar (Ms Bar), baz (Dr Baz)"),
            expected
        );
        assert_eq!(
            parse_name_list("foo (Mr Foo) bar (Ms Bar) (the other one), baz (Dr Baz)"),
            expected
        );
    }
}
